CREATE TRIGGER trg_ierc_immutable BEFORE UPDATE ON inv_execution_retention_claim
FOR EACH ROW
BEGIN
    IF NOT (BINARY NEW.id <=> BINARY OLD.id) OR
        NOT (BINARY NEW.retention_no <=> BINARY OLD.retention_no) OR
        NOT (BINARY NEW.component_no <=> BINARY OLD.component_no) OR
