        NOT (BINARY NEW.created_at <=> BINARY OLD.created_at) OR
        NOT (BINARY NEW.created_by <=> BINARY OLD.created_by) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Execution stock retention immutable original';
    END IF;
    IF OLD.state IN ('RELEASED_NO_EFFECT','SEALED_NO_EFFECT') AND (NEW.state<>OLD.state OR
        NOT (BINARY NEW.no_effect_seal_json <=> BINARY OLD.no_effect_seal_json) OR
        NOT (BINARY NEW.no_effect_seal_no <=> BINARY OLD.no_effect_seal_no) OR
        NOT (NEW.no_effect_seal_revision <=> OLD.no_effect_seal_revision) OR
        NOT (BINARY NEW.no_effect_seal_hash <=> BINARY OLD.no_effect_seal_hash)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Retention seal is permanent';
    END IF;
    IF OLD.issue_observation_hash IS NOT NULL AND (
        NOT (BINARY NEW.issue_observation_json <=> BINARY OLD.issue_observation_json) OR
        NOT (BINARY NEW.issue_observation_hash <=> BINARY OLD.issue_observation_hash)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Retention issue observation is immutable';
    END IF;
END$$

CREATE TRIGGER trg_ier_no_delete BEFORE DELETE ON inv_execution_retention
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Execution stock retention history cannot be deleted';
END$$
DELIMITER ;
